<?php
session_start();require 'config.php';if(!isset($_SESSION['user_id'])){header('Location:login.php');exit;}$id=(int)($_GET['course']??0);$s=$conn->prepare('SELECT id,title,price FROM courses WHERE id=?');$s->bind_param('i',$id);$s->execute();$course=$s->get_result()->fetch_assoc();if(!$course)die('دوره پیدا نشد');if($_SERVER['REQUEST_METHOD']==='POST'){$u=$_SESSION['user_id'];$p=$conn->prepare("INSERT INTO purchases(user_id,course_id,status) VALUES(?,?, 'paid')");$p->bind_param('ii',$u,$id);$p->execute();header('Location:success.php?course='.$id);exit;}?><!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>پرداخت آزمایشی</title><link rel='stylesheet' href='style.css'></head><body><main class='formbox'><h1>💳 پرداخت آزمایشی</h1><h2><?=htmlspecialchars($course['title'])?></h2><p>مبلغ: <?=number_format($course['price'])?> تومان</p><p>این پرداخت واقعی نیست.</p><form method='post'><button class='btn'>پرداخت آزمایشی</button></form><a href='courses.php'>بازگشت</a></main></body></html>